def is_simple_power(x, n):
    if n == 1:
        return x == 1
    if n == 0:
        return x == 1
    import math
    if x <= 0:
        return False
    if n < 0:
        # For negative n, n**int can be positive or negative depending on int
        # We need to check if there exists an integer k such that n**k = x
        # Since x > 0, k must be even if n < 0
        # Let's try both positive and negative exponents
        for k in range(-100, 101):
            if n ** k == x:
                return True
        return False
    # For positive n
    if x == 1:
        return True
    # Check if x is a power of n
    # We can use logarithms to find the exponent
    try:
        exponent = math.log(x) / math.log(n)
    except ValueError:
        return False
    # Check if exponent is close to an integer
    rounded_exponent = round(exponent)
    if abs(exponent - rounded_exponent) < 1e-10:
        return n ** int(rounded_exponent) == x
    return False

